def transform(grid):
    h, w = len(grid), len(grid[0])
    sep_row = next((i for i, row in enumerate(grid) if len(set(row)) == 1 and i == h - i - 1), None)
    if sep_row is not None:
        a, b = grid[:sep_row], grid[sep_row+1:]
        divider = grid[sep_row][0]
        colors_a = {v for row in a for v in row}
        colors_b = {v for row in b for v in row}
        shared = (colors_a & colors_b) - {divider}
        color = next(iter(shared))
        return [[3 if x == color and y == color else color for x, y in zip(ra, rb)] for ra, rb in zip(a, b)]
    sep_col = next(j for j in range(w) if len({grid[i][j] for i in range(h)}) == 1)
    a = [row[:sep_col] for row in grid]
    b = [row[sep_col+1:] for row in grid]
    divider = grid[0][sep_col]
    colors_a = {v for row in a for v in row}
    colors_b = {v for row in b for v in row}
    shared = (colors_a & colors_b) - {divider}
    color = next(iter(shared))
    return [[3 if x == color and y == color else color for x, y in zip(ra, rb)] for ra, rb in zip(a, b)]
